-- Initial file generated by Claude Sonnet 5.5

module Zocalo.Gallery.AuthSpec(tests) where

import Test.Framework(Test, testGroup)
import Test.Framework.Providers.HUnit(testCase)
import Test.HUnit((@?=))

import Zocalo.Gallery.Auth.AuthorizedUser(
    AuthorizedStudent(AStudent), AuthorizedTeacher(ATeacher), AuthorizedUser(readUser)
  )

import Zocalo.Gallery.Entity.LowerText(asLowerText, lowText)

tests :: Test
tests =
  testGroup "Zocalo.Gallery (auth + entities)" $
    [ testGroup "LowerText"
        [ testCase "lower-cases the text" $
            lowText (asLowerText "Teacher@Example.COM") @?= "teacher@example.com"
        , testCase "makes differently-cased addresses equal" $
            asLowerText "A@B.c" @?= asLowerText "a@b.C"
        , testCase "is idempotent" $
            asLowerText (lowText $ asLowerText "MiXeD") @?= asLowerText "MiXeD"
        ]

    , testGroup "readUser (student JWT subject, \"<id>|<name>\")"
        [ testCase "parses ID and name" $
            (readUser "42|Ana" :: Maybe AuthorizedStudent) @?= Just (AStudent 42 "Ana")
        , testCase "keeps everything after the first pipe as the name" $
            (readUser "7|A|B" :: Maybe AuthorizedStudent) @?= Just (AStudent 7 "A|B")
        , testCase "allows an empty name" $
            (readUser "42|" :: Maybe AuthorizedStudent) @?= Just (AStudent 42 "")
        , testCase "rejects a non-numeric id" $
            (readUser "abc|Ana" :: Maybe AuthorizedStudent) @?= Nothing
        , testCase "rejects a missing id" $
            (readUser "|Ana" :: Maybe AuthorizedStudent) @?= Nothing
        , testCase "rejects a negative id" $
            (readUser "-1|Ana" :: Maybe AuthorizedStudent) @?= Nothing
        , testCase "rejects a subject with no pipe at all" $
            (readUser "42" :: Maybe AuthorizedStudent) @?= Nothing
        ]

    , testGroup "readUser (teacher JWT subject, an e-mail address)"
        [ testCase "lower-cases the address" $
            (readUser "Teach@X.com" :: Maybe AuthorizedTeacher) @?=
              Just (ATeacher $ asLowerText "teach@x.com")
        ]
    ]
